import{_ as s,l as i,o as e,c as l,v as t,p as A,x as r,d as n,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"SACK","description":"","frontmatter":{"title":"SACK","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcp-sack.md","filePath":"cs/tcp-sack.md","lastUpdated":1789023840000}'),p={name:"cs/tcp-sack.md"};function C(h,a,E,_,K,S){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="sack" tabindex="-1">SACK <a class="header-anchor" href="#sack" aria-label="Permalink to &quot;SACK&quot;">​</a></h1><div class="epigraph"><p>累计 ACK 只推进前缀；选择确认把已收到的不连续块告诉发送方，重传针对空洞而不是从洞口整段重来。</p><footer>—— 据 RFC 2018 选择确认；RFC 793 的累计确认仍是基线；Kurose and Ross</footer></div><p><a href="/cs/tcp-rto">上一课</a>钉死何时超时重传。本课不重做 Karn。缺口是丢包形状：窗口里丢了中间几段时，累计 ACK 反复报同一个前缀，发送方只能猜或超时后从洞口重拉。SACK 选项列出已收到的序号块。本课不把接收窗口通告写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/tcp-seq-rexmit">序号与重传</a> 用累计 ACK。管道长、窗口大时，一次丢几个段会导致不必要的重传（Go-Back-N 式浪费）。SACK：接收方在 ACK 里带若干块「左沿、右沿」；发送方维护计分板，只重发未被累计也未被 SACK 覆盖的段。缺口是<strong>空洞的显式信号</strong>，仍服从累计 ACK 推进提交序号。</p><p><span class="marginnote">SACK 是选项，需握手协商。DSACK 后来报告重复收到的块，帮助区分重传与乱序。本课只钉选择确认的数据平面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>接收乱序段：缓存在重组队列，发 ACK（常带 SACK）。发送方根据计分板决定重传集合；累计 ACK 前移时裁掉计分板前缀。与 RTO 的关系：SACK 不取消超时，只减少盲目重传。流控窗口下一课才限制「能飞多少」。</p>',8)),(e(),A(d,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOLE%5B%22%E7%AA%97%E5%8F%A3%E4%B8%AD%E7%9A%84%E7%A9%BA%E6%B4%9E%22%5D%20--%3E%20CUM%5B%22%E7%B4%AF%E8%AE%A1%20ACK%20%E5%81%9C%E5%9C%A8%E6%B4%9E%E5%8F%A3%22%5D%0A%20%20CUM%20--%3E%20SB%5B%22SACK%20%E5%9D%97%E5%A1%AB%E8%AE%A1%E5%88%86%E6%9D%BF%22%5D%0A%20%20SB%20--%3E%20REX%5B%22%E5%8F%AA%E9%87%8D%E5%8F%91%E7%A9%BA%E6%B4%9E%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SACK 把接收缓冲的占用情况部分暴露给发送方，使重传与 <a href="/cs/io-dma">DMA</a> 进出的字节更接近真实丢失。它不增加可靠性规格：没有 SACK 的 TCP 仍可靠，只是更慢、更浪费。端到端校验与序号仍然是正确性来源。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 FACK 与全部恢复算法当标准必背，不引入 QUIC 的 ACK 范围作为本课对象（后课对照）。接收方还能收多少字节，下一课 <code>rwnd</code>。</p><p>后课默认：发送方可以知道哪些块已到。发送太多仍会淹没对端缓冲，下一课流控。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SACK 报告不连续块；重传对准空洞。</li><li>累计 ACK 仍是提交前缀。</li><li>接收窗口是下一课。</li><li>出处：RFC 2018；RFC 793；Kurose and Ross。</li></ul>',7))])}const f=s(p,[["render",C]]);export{u as __pageData,f as default};
